//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/ctype` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/ctype_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_ctype_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.

use super::{assert_format, locale_available, run_case};

/// Replays php-src `001.phpt`.
#[test]
fn test_php_src_ctype_001() {
    let out = run_case(r#"<?php
setlocale(LC_ALL,"C");

function ctype_test_001($function) {
    $n=0;
    for($a=0;$a<256;$a++) {
        if($function($a)) $n++;
    }
    echo "$function $n\n";
}

ctype_test_001("ctype_lower");
ctype_test_001("ctype_upper");
ctype_test_001("ctype_alpha");
ctype_test_001("ctype_digit");
ctype_test_001("ctype_alnum");
ctype_test_001("ctype_cntrl");
ctype_test_001("ctype_graph");
ctype_test_001("ctype_print");
ctype_test_001("ctype_punct");
ctype_test_001("ctype_space");
ctype_test_001("ctype_xdigit");
"#, &[(r#"error_reporting"#, r#"E_ALL&~E_DEPRECATED"#)], &[]);
    assert_eq!(out, r#"ctype_lower 26
ctype_upper 26
ctype_alpha 52
ctype_digit 10
ctype_alnum 62
ctype_cntrl 33
ctype_graph 94
ctype_print 95
ctype_punct 32
ctype_space 6
ctype_xdigit 22"#);
}

/// Replays php-src `002.phpt`.
#[test]
fn test_php_src_ctype_002() {
    let out = run_case(r#"<?php

setlocale(LC_ALL,"C");
print "LOCALE is '" . setlocale(LC_ALL,0) . "'\n";

function ctype_test_002($function) {
    $n1 = $n2 = $n3 = 0;
    // test portable POSIX characters 0..127
    for ($a=0;$a<128;$a++) {
        $c = chr($a);
        if($function($c)) $n1++;
        if($function("$c$c$c")) $n2++;
        if($function("1-$c$c$c-x")) $n3++;
    }
    print "$function $n1 $n2 $n3\n";
}

ctype_test_002("ctype_lower");
ctype_test_002("ctype_upper");
ctype_test_002("ctype_alpha");
ctype_test_002("ctype_digit");
ctype_test_002("ctype_alnum");
ctype_test_002("ctype_cntrl");
ctype_test_002("ctype_graph");
ctype_test_002("ctype_print");
ctype_test_002("ctype_punct");
ctype_test_002("ctype_space");
ctype_test_002("ctype_xdigit");

"#, &[], &[]);
    assert_format(&out, r#"LOCALE is '%s'
ctype_lower 26 26 0
ctype_upper 26 26 0
ctype_alpha 52 52 0
ctype_digit 10 10 0
ctype_alnum 62 62 0
ctype_cntrl 33 33 0
ctype_graph 94 94 94
ctype_print 95 95 95
ctype_punct 32 32 0
ctype_space 6 6 0
ctype_xdigit 22 22 0"#);
}

/// Replays php-src `bug25745.phpt`.
#[test]
fn test_php_src_ctype_bug25745() {
    let out = run_case(r#"<?php
$funcs = array(
    "ctype_alnum", "ctype_alpha", "ctype_cntrl", "ctype_digit",
    "ctype_graph", "ctype_lower", "ctype_print", "ctype_punct",
    "ctype_space", "ctype_upper", "ctype_xdigit"
);

foreach ($funcs as $ctype_func) {
    for ($i = 0; $i < 256; $i++) {
        $a = $ctype_func($i);
        $b = $ctype_func(chr($i));
        if ($a != $b) {
            echo "broken... $ctype_func($i) = $a, $ctype_func(chr($i)) = $b\n";
            exit;
        }
    }
}
echo "ok\n";
"#, &[(r#"error_reporting"#, r#"E_ALL&~E_DEPRECATED"#)], &[]);
    assert_eq!(out, r#"ok"#);
}

