/// Replays php-src `lc_ctype_inheritance.phpt`.
#[test]
fn test_php_src_ctype_lc_ctype_inheritance() {
    if !locale_available("de_DE") {
        eprintln!("skip: de_DE locale unavailable");
        return;
    }
    let out = run_case(r#"<?php

echo "inherited\n";
echo 'ctype_lower(\xe4): ' . (ctype_lower("\xe4") ? 'y' : 'n') . "\n";
echo 'preg_match(\w, \xe4): ';
var_dump(preg_match('/\w/', "\xe4"));

var_dump(setlocale(LC_CTYPE, "0"));
echo 'ctype_lower(\xe4): ' . (ctype_lower("\xe4") ? 'y' : 'n') . "\n";
echo 'preg_match(\w, \xe4): ';
var_dump(preg_match('/\w/', "\xe4"));

echo "de_DE\n";
var_dump(setlocale(LC_CTYPE, "de_DE", "de-DE") !== false);
echo 'ctype_lower(\xe4): ' . (ctype_lower("\xe4") ? 'y' : 'n') . "\n";
echo 'preg_match(\w, \xe4): ';
var_dump(preg_match('/\w/', "\xe4"));
"#, &[], &[(r#"LC_CTYPE"#, r#"de_DE"#)]);
    assert_format(&out, r#"inherited
ctype_lower(\xe4): n
preg_match(\w, \xe4): int(0)
string(%d) "C%r(\.UTF-8)?%r"
ctype_lower(\xe4): n
preg_match(\w, \xe4): int(0)
de_DE
bool(true)
ctype_lower(\xe4): y
preg_match(\w, \xe4): int(1)"#);
}
